    const row = (c.rows || []).find((r) => r.kind === kind);
    const held = (row?.scenes || c.scenes || []).flatMap((x) => st(h, x.entity)?.attributes?.entity_id || []).filter((id) => id.startsWith(want));
    const areas = new Set(held.map((id) => areaOf(h, id)).filter(Boolean));
