      const readings = this.readings();
      const chart = `${this.chartPeriods()}${this.chart(this._config.entity, this._config.floor ? "Пол" : "В комнате", tone ? `${tone}${calm ? " calm" : ""}` : "", 96)}${this.chartHistory()}`;
