          const dg = String(Math.abs(step)).includes(".") ? String(Math.abs(step)).split(".")[1].length : 0;
          const nv = Number(Math.min(num(a.max) ?? Infinity, Math.max(num(a.min) ?? -Infinity, v + step)).toFixed(dg));
